package main

import (
	"fmt"
	"log"
	"net/http"
	"time"
)

// handlePing 是处理函数：签名由 net/http 规定
// w 是「写回客户端的管道」，r 是「客户端发过来的请求」
func handlePing(w http.ResponseWriter, r *http.Request) {
	// 先写响应头。Header 必须在第一次写 body 之前设置，一旦写 body 就锁死了
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)

	// 把 JSON 写出去。这里故意用 fmt.Fprintf 而非拼接整个字符串
	fmt.Fprintf(w, `{"pong":true,"path":%q,"at":%q}`,
		r.URL.Path,
		time.Now().Format(time.RFC3339),
	)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/ping", handlePing)
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "404 页面不存在: "+r.URL.Path, http.StatusNotFound)
	})

	addr := "127.0.0.1:8080"

	// ListenAndServe 会阻塞在 main 里，直到出错或被关掉。
	// 它返回的第一个 error 才是端口冲突的信号，所以不要写成 srv.ListenAndServe()
	srv := &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 3 * time.Second,
	}

	log.Printf("服务已启动: http://%s  (Ctrl-C 退出)", addr)
	if err := srv.ListenAndServe(); err != nil {
		log.Fatalf("启动失败: %v", err)
	}
}

