package main

import (
	"fmt"
	"os"
	"strings"
)

// getenvOr 第一档：取不到就用默认值，服务照常启动。
// 适合监听地址、时区、应用名这类「没有也能跑」的项。
// 用 LookupEnv 而不是 Getenv：Getenv 分不清「没设置」和「设成了空串」
func getenvOr(key, fallback string) string {
	if v, ok := os.LookupEnv(key); ok && strings.TrimSpace(v) != "" {
		return v
	}
	return fallback
}

// mustGetenv 第二档：必须存在，缺了立刻退出。
// 适合密码、密钥、租户 ID 这类「没有就不该启动」的项
func mustGetenv(key string) string {
	v := getenvOr(key, "")
	if v == "" {
		// 只报变量名，绝不报值——值可能就打印在终端历史里
		fmt.Fprintf(os.Stderr, "缺少必需的环境变量 %s：请在 shell 或 .env 里设置后重试\\n", key)
		os.Exit(1)
	}
	return v
}

// Config 把所有配置一次性收集成一个结构体。
// 后面任何函数都不应该再去碰 os.Getenv
type Config struct {
	AppName    string
	HTTPAddr   string
	DBHost     string
	DBPort     string
	DBUser     string
	DBPassword string
	DBName     string
}

func loadConfig() Config {
	return Config{
		AppName:    getenvOr("HC_APP_NAME", "homeos"),
		HTTPAddr:   getenvOr("HC_HTTP_ADDR", "127.0.0.1:8080"),
		DBHost:     getenvOr("HC_DB_HOST", "127.0.0.1"),
		DBPort:     getenvOr("HC_DB_PORT", "5432"),
		DBUser:     getenvOr("HC_DB_USER", "homeos"),
		DBPassword: mustGetenv("HC_DB_PASSWORD"),
		DBName:     getenvOr("HC_DB_NAME", "homecube"),
	}
}

// DSN 拼出连接串。密码在里面，所以 mask 之后再打印
func (c Config) DSN() string {
	return fmt.Sprintf("postgres://%s:%s@%s:%s/%s?sslmode=disable",
		c.DBUser, c.DBPassword, c.DBHost, c.DBPort, c.DBName)
}

// mask：打印时把中间遮住，保留首尾方便确认是哪一个密码
func mask(s string) string {
	if len(s) <= 2 {
		return strings.Repeat("*", len(s))
	}
	return s[:1] + strings.Repeat("*", len(s)-2) + s[len(s)-1:]
}

func main() {
	cfg := loadConfig()

	fmt.Printf("app       = %s\\n", cfg.AppName)
	fmt.Printf("http      = %s\\n", cfg.HTTPAddr)
	fmt.Printf("db user   = %s\\n", cfg.DBUser)
	fmt.Printf("db host   = %s:%s/%s\\n", cfg.DBHost, cfg.DBPort, cfg.DBName)
	fmt.Printf("db pass   = %s  (长度 %d)\\n", mask(cfg.DBPassword), len(cfg.DBPassword))

	// mask 之后依然能连库：证明打码只是给人看的，没改真实值
	fmt.Printf("DSN(打印版) = %s\\n", maskDSN(cfg.DSN(), cfg.DBPassword))
}

func maskDSN(dsn, password string) string {
	return strings.ReplaceAll(dsn, password, mask(password))
}

