package main

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
)

// Envelope 是 HomeOS 所有接口的统一响应体。
// 前端只需要写一套处理逻辑：code == 0 读 data，否则弹 message
type Envelope struct {
	Code    int         `json:"code"`    // 0 成功，非 0 业务错误
	Message string      `json:"message"` // 给人看的中文提示
	Data    interface{} `json:"data"`    // 成功时的载荷，失败时为 null
	At      string      `json:"at"`      // 服务端 ISO8601 时间
}

// 系统级错误码：1001 段给参数，3001 段给权限，4001 段给冲突
const (
	CodeOK           = 0
	CodeInvalidParam = 1001
	CodeUnauthorized = 3001
)

func nowISO() string {
	// 本地时区输出成 +08:00 这样的偏移量，比 UTC 的 Z 更适合人看
	return time.Now().Format("2006-01-02T15:04:05-07:00")
}

// getenvOr 与 D4 相同：第一档，允许默认值
func getenvOr(key, fallback string) string {
	if v, ok := os.LookupEnv(key); ok && strings.TrimSpace(v) != "" {
		return v
	}
	return fallback
}

// ok 成功响应：HTTP 200 + code 0
func ok(w http.ResponseWriter, data interface{}) {
	writeJSON(w, http.StatusOK, Envelope{
		Code: CodeOK, Message: "ok", Data: data, At: nowISO(),
	})
}

// fail 失败响应：HTTP 状态码给基础设施看，code 给业务看，两者各自独立
func fail(w http.ResponseWriter, status int, code int, msg string) {
	writeJSON(w, status, Envelope{
		Code: code, Message: msg, Data: nil, At: nowISO(),
	})
}

func writeJSON(w http.ResponseWriter, status int, env Envelope) {
	// 顺序不能反：Header 必须在 WriteHeader 和写 body 之前
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("X-Service-Name", "svc-homeos")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(env) // Encode 会自动换行
}

// healthz 只回答「能不能服务」，不要在这里查数据库
func healthz(w http.ResponseWriter, r *http.Request) {
	ok(w, map[string]interface{}{
		"status": "up",
		"app":    getenvOr("HC_APP_NAME", "homeos"),
		"uptime": time.Since(startedAt).Round(time.Second).String(),
	})
}

// whoami 回答「服务认为调用者是谁」。S0 读 header，S4 换成读 JWT
func whoami(w http.ResponseWriter, r *http.Request) {
	memberID := r.Header.Get("X-Member-Id")
	familyID := r.Header.Get("X-Family-Id")
	if memberID == "" {
		// 没有身份就诚实地说未认证，而不是编一个默认用户出来
		fail(w, http.StatusUnauthorized, CodeUnauthorized, "缺少 X-Member-Id 请求头")
		return
	}
	role := r.Header.Get("X-Role")
	if role == "" {
		role = "member" // S4 之前没有真角色，兜底一个
	}
	ok(w, map[string]interface{}{
		"member_id": memberID,
		"family_id": familyID,
		"role":      role,
		"source":    "header", // S4 之后这里会变成 "jwt"
	})
}

var startedAt = time.Now()

func main() {
	addr := getenvOr("HC_HTTP_ADDR", "127.0.0.1:8080")

	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", healthz)
	mux.HandleFunc("/whoami", whoami)
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		fail(w, http.StatusNotFound, 404, "没有这个接口: "+r.URL.Path)
	})

	srv := &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 3 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	// 优雅关闭：收到 SIGTERM/SIGINT 时，停止接新请求，等在途请求做完再退
	// 容器重启时会先发 SIGTERM，给 5 秒退出窗口（S13 会展开讲）
	idle := make(chan struct{})
	go func() {
		sigCh := make(chan os.Signal, 1)
		signal.Notify(sigCh, os.Interrupt, syscall.SIGTERM)
		<-sigCh
		log.Println("收到退出信号，开始优雅关闭...")
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := srv.Shutdown(ctx); err != nil {
			log.Printf("优雅关闭失败: %v", err)
		}
		close(idle)
	}()

	log.Printf("svc-homeos 启动: http://%s", addr)
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("启动失败: %v", err)
	}
	<-idle
	log.Println("已退出")
}

