package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"
)

// Envelope 与 S0 D6 保持一致：契约不能因为换端口而变
type Envelope struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data"`
	At      string      `json:"at"`
}

func writeJSON(w http.ResponseWriter, status int, e Envelope) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(e)
}

func ok(w http.ResponseWriter, data interface{}) {
	writeJSON(w, http.StatusOK, Envelope{0, "ok", data, "2026-10-16T09:00:00+08:00"})
}

func fail(w http.ResponseWriter, status, code int, msg string) {
	writeJSON(w, status, Envelope{code, msg, nil, "2026-10-16T09:00:00+08:00"})
}

// POST /echo 接受一个 JSON，放大后返回。
// 这里会依次演示三种失败：405 方法不对、400 语法错、422 语义错
func echo(w http.ResponseWriter, r *http.Request) {
	// ① 方法检查：路径存在但方法不对是 405，必须带 Allow 头
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", "POST") // 标准要求：告诉客户端应该用什么
		fail(w, http.StatusMethodNotAllowed, 1405, "这个接口只接受 POST，收到的是 "+r.Method)
		return
	}

	// ② Content-Type 检查：没有 JSON 声明就别费劲解析
	ct := r.Header.Get("Content-Type")
	if !strings.HasPrefix(ct, "application/json") {
		fail(w, http.StatusUnsupportedMediaType, 1415,
			"Content-Type 必须是 application/json，收到的是 "+ct)
		return
	}

	// ③ 限流 body 大小。r.Body 只能读一次，所以限制必须在读之前设
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // 1MB 上限

	body, err := io.ReadAll(r.Body)
	if err != nil {
